const field = "h-10 rounded-[10px]";
const dash = (v: string | null | undefined) => (v && v.trim() ? v : "—");

function IconStat({ icon: Icon, label, value, note }: { icon: typeof Users; label: string; value: string; note: string }) { return <Panel><div className="flex items-start justify-between"><div><p className="text-sm text-muted-foreground">{label}</p><p className="mt-2 text-3xl font-semibold tabular-nums">{value}</p><p className="mt-2 text-xs text-muted-foreground">{note}</p></div><span className="grid size-10 place-items-center rounded-xl bg-muted"><Icon className="size-5" /></span></div></Panel>; }
function SearchBox({ value, onChange, placeholder = "Search" }: { value: string; onChange: (v: string) => void; placeholder?: string }) { return <div className="relative"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" /><Input className={cn(field, "pl-9")} value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} /></div>; }
function DataRow({ children }: { children: React.ReactNode }) { return <div className="grid gap-3 border-b border-border px-1 py-4 last:border-0 md:grid-cols-[minmax(220px,1.5fr)_1fr_1fr_auto] md:items-center">{children}</div>; }

function useClinicName() { const { clinic } = useAuth(); return clinic?.name ?? "your clinic"; }
function clientStatus(bookings: number) { return bookings > 1 ? "Active Patient" : "New Client"; }
type TranscriptTurn = { speaker: string; text: string; time: string };
function parseTranscript(value: unknown): TranscriptTurn[] {
  if (!Array.isArray(value)) return [];
  return value.filter((t): t is TranscriptTurn => !!t && typeof t === "object" && "speaker" in t && "text" in t);
}

// ------------------------------------------------------------------ login
export function LoginPage() {
  const navigate = useNavigate();
  const { signIn, sendPasswordReset, session, loading } = useAuth();
  const [forgot, setForgot] = useState(false); const [sent, setSent] = useState(false); const [error, setError] = useState("");
  const [email, setEmail] = useState(""); const [password, setPassword] = useState(""); const [show, setShow] = useState(false);
  const [resetEmail, setResetEmail] = useState(""); const [busy, setBusy] = useState(false);

  useEffect(() => { if (!loading && session) void navigate({ to: "/home" }); }, [loading, session, navigate]);

  const submit = async () => {
    if (!email.trim() || !password) { setError("Enter your email and password to continue."); return; }
    setBusy(true);
    const { error: signInError } = await signIn(email, password);
    setBusy(false);
    if (signInError) { setError("Incorrect email or password."); return; }
    setError(""); toast.success("Signed in"); void navigate({ to: "/home" });
  };

  return <main className="grid min-h-screen place-items-center bg-background p-4"><div className="w-full max-w-[430px]"><div className="mb-8 flex justify-center"><AperoMark /></div><Panel className="p-7 sm:p-9"><h1 className="text-2xl font-semibold">Welcome back</h1><p className="mt-2 text-sm text-muted-foreground">Sign in to access your clinic dashboard.</p>{error && <div className="mt-5 rounded-[10px] border border-destructive/30 bg-destructive/5 p-3 text-sm text-destructive">{error}</div>}<form className="mt-7 space-y-4" onSubmit={(e) => { e.preventDefault(); void submit(); }}><div><Label htmlFor="login-email">Email address</Label><Input id="login-email" type="email" autoComplete="email" className={cn(field, "mt-2")} value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@clinic.com" /></div><div><div className="flex justify-between"><Label htmlFor="login-password">Password</Label><Button type="button" variant="link" className="h-auto p-0 text-xs" onClick={() => { setSent(false); setForgot(true); }}>Forgot password?</Button></div><div className="relative"><Input id="login-password" type={show ? "text" : "password"} autoComplete="current-password" className={cn(field, "mt-2 pr-10")} value={password} onChange={(e) => setPassword(e.target.value)} /><button type="button" onClick={() => setShow(!show)} aria-label={show ? "Hide password" : "Show password"} className="absolute right-3 top-1/2 mt-1 -translate-y-1/2 text-muted-foreground">{show ? <EyeOff className="size-4" /> : <Eye className="size-4" />}</button></div></div><Button type="submit" disabled={busy} className="h-10 w-full rounded-[10px]">{busy ? "Signing in…" : "Sign in"}</Button></form></Panel><p className="mt-6 text-center text-xs text-muted-foreground">Clinic accounts are created by Apero. Need access? <a className="font-semibold text-foreground underline" href="mailto:apero.hq@gmail.com">Contact Apero support</a></p></div><Dialog open={forgot} onOpenChange={setForgot}><DialogContent className="rounded-2xl"><DialogHeader><DialogTitle>{sent ? "Check your email" : "Reset your password"}</DialogTitle><DialogDescription>{sent ? "We’ve sent a secure reset link to your email address." : "Enter your email and we’ll send you a secure reset link."}</DialogDescription></DialogHeader>{sent ? <CheckCircle2 className="mx-auto size-12 text-success" /> : <div><Label htmlFor="reset-email">Email address</Label><Input id="reset-email" type="email" className={cn(field, "mt-2")} value={resetEmail} onChange={(e) => setResetEmail(e.target.value)} placeholder="you@clinic.com" /></div>}<DialogFooter><Button className="rounded-[10px]" onClick={async () => { if (sent) { setForgot(false); return; } if (!resetEmail.trim()) { toast.error("Enter your email address first."); return; } const { error: resetError } = await sendPasswordReset(resetEmail); if (resetError) { toast.error("Could not send the reset link."); return; } setSent(true); toast.success("Reset link sent"); }}>{sent ? "Return to sign in" : "Send reset link"}</Button></DialogFooter></DialogContent></Dialog></main>;
}

export function ResetPasswordPage() {
  const navigate = useNavigate();
  const { updatePassword, session, loading } = useAuth();
  const [pw, setPw] = useState(""); const [confirm, setConfirm] = useState(""); const [busy, setBusy] = useState(false);
  const rules = [pw.length >= 8, /[A-Z]/.test(pw), /\d/.test(pw)];
  const ready = rules.every(Boolean) && pw === confirm;
  return <main className="grid min-h-screen place-items-center bg-background p-4"><div className="w-full max-w-[430px]"><div className="mb-8 flex justify-center"><AperoMark /></div><Panel className="p-7 sm:p-9"><h1 className="text-2xl font-semibold">Choose a new password</h1><p className="mt-2 text-sm text-muted-foreground">{loading ? "Checking your reset link…" : session ? "Enter a new password for your Apero account." : "Open the reset link from your email to continue."}</p><div className="mt-6 grid gap-4"><div><Label htmlFor="new-pw">New password</Label><Input id="new-pw" type="password" autoComplete="new-password" className={cn(field, "mt-2")} value={pw} onChange={(e) => setPw(e.target.value)} /></div><div><Label htmlFor="confirm-pw">Confirm password</Label><Input id="confirm-pw" type="password" autoComplete="new-password" className={cn(field, "mt-2")} value={confirm} onChange={(e) => setConfirm(e.target.value)} /></div><div className="space-y-2 rounded-xl bg-muted p-3 text-xs">{["At least 8 characters", "At least 1 uppercase letter", "At least 1 number"].map((r, i) => <div key={r} className={cn("flex items-center gap-2", rules[i] ? "text-success-strong" : "text-muted-foreground")}><CheckCircle2 className="size-3" />{r}</div>)}</div><Button disabled={!ready || busy || !session} onClick={async () => { setBusy(true); const { error } = await updatePassword(pw); setBusy(false); if (error) { toast.error("Could not update the password."); return; } toast.success("Password updated"); void navigate({ to: "/home" }); }}>Update password</Button><Button variant="ghost" asChild><Link to="/login">Back to sign in</Link></Button></div></Panel></div></main>;
}

// ------------------------------------------------------------------- home
export function HomePage() {
  const { profile } = useAuth();
  const clinicName = useClinicName();
  const clients = useClients(); const staffList = useStaff();
  const appointments = useAppointments(); const conversations = useConversations();
  const [range, setRange] = useState("today");
  const clientOf = (id: string | null) => clients.find((c) => c.id === id);
  const attention = conversations.filter((c) => ["Needs Review", "Missed"].includes(c.status));
  const next = appointments.find((a) => a.status === "Booked");
  const nextClient = clientOf(next?.client_id ?? null);
  const nextStaff = staffList.find((s) => s.id === next?.staff_id);
  const booked = appointments.filter((a) => a.status === "Booked").length;
  const minutes = conversations.reduce((sum, c) => sum + c.duration_seconds, 0) / 60;
  return <><PageHeader title={`Welcome, ${profile?.full_name ?? "there"}`} description={`Here’s what’s happening at ${clinicName} today.`} action={<div className="flex items-center gap-2"><Select value={range} onValueChange={(v) => { setRange(v); toast.success(`Showing ${v === "today" ? "today" : v === "week" ? "this week" : "this month"}`); }}><SelectTrigger className="w-[150px]"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="today">Today</SelectItem><SelectItem value="week">This week</SelectItem><SelectItem value="month">This month</SelectItem></SelectContent></Select><StatusBadge status="Online" /></div>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><IconStat icon={Phone} label="Calls answered" value={String(conversations.length)} note="Handled by Apero" /><IconStat icon={CalendarDays} label="Appointments booked" value={String(booked)} note="Currently scheduled" /><IconStat icon={Clock} label="Time saved" value={`${(minutes / 60).toFixed(1)}h`} note="Across your front desk" /><IconStat icon={Users} label="Clients" value={String(clients.length)} note="In your clinic records" /></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.35fr_.65fr]"><Panel><PanelTitle detail={<Link to="/conversations" className="text-xs font-medium text-muted-foreground hover:text-foreground">View all</Link>}>Needs your attention</PanelTitle><div className="space-y-3">{attention.length ? attention.map((c) => { const client = clientOf(c.client_id); return <Link key={c.id} to="/conversations/$id" params={{ id: c.id }} className="flex items-center gap-3 rounded-xl border border-warning-border bg-warning-soft p-4"><Avatar initials={client?.initials ?? "?"} /><div className="min-w-0 flex-1"><div className="font-medium">{c.title}</div><div className="truncate text-xs text-muted-foreground">{client?.name ?? dash(c.caller_phone)} · {formatTime(c.started_at)}</div></div><StatusBadge status={c.status} /></Link>; }) : <Empty>Nothing needs your attention.</Empty>}</div></Panel><Panel><PanelTitle>Next appointment</PanelTitle>{next ? <><p className="text-2xl font-semibold">{formatTime(next.start_time)}</p><p className="mt-1 text-sm text-muted-foreground">{formatDate(next.start_time)} · {durationLabel(next.start_time, next.end_time)}</p><div className="my-5 flex items-center gap-3"><Avatar initials={nextClient?.initials ?? "?"} /><div>{nextClient ? <Link to="/clients/$id" params={{ id: nextClient.id }} className="font-semibold hover:underline">{nextClient.name}</Link> : <span className="font-semibold">Unknown client</span>}<p className="text-xs text-muted-foreground">{next.service} · {nextStaff?.name ?? "Unassigned"}</p></div></div><div className="flex flex-wrap items-center gap-2"><StatusBadge status={next.status} /><Button size="sm" variant="outline" asChild><Link to="/calendar">Open in calendar</Link></Button>{nextClient && <Button size="sm" variant="ghost" asChild><Link to="/clients/$id" params={{ id: nextClient.id }}>View client</Link></Button>}</div></> : <Empty>No upcoming appointments.</Empty>}</Panel></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.35fr_.65fr]"><Panel><PanelTitle detail={<Link to="/conversations" className="text-xs font-medium text-muted-foreground hover:text-foreground">Open call log</Link>}>Recent conversations</PanelTitle>{conversations.length ? conversations.slice(0, 4).map((c) => { const client = clientOf(c.client_id); return <DataRow key={c.id}><div className="flex items-center gap-3"><Avatar initials={client?.initials ?? "?"} /><div><Link to="/conversations/$id" params={{ id: c.id }} className="font-medium hover:underline">{client?.name ?? dash(c.caller_phone)}</Link><p className="text-xs text-muted-foreground">{c.title}</p></div></div><span className="text-sm text-muted-foreground">{formatTime(c.started_at)}</span><span className="text-sm tabular-nums">{formatDuration(c.duration_seconds)}</span><StatusBadge status={c.status} /></DataRow>; }) : <Empty>No conversations yet.</Empty>}</Panel><Panel className="bg-primary text-primary-foreground"><div className="flex items-center gap-2 text-sm font-semibold"><span className="relative flex size-2"><span className="absolute inline-flex size-full animate-ping rounded-full bg-success opacity-75" /><span className="relative size-2 rounded-full bg-success" /></span>Apero Active</div><p className="mt-5 text-2xl font-semibold">Always ready to answer.</p><p className="mt-2 text-sm text-primary-foreground/70">Your clinic line is online and taking calls in English and Arabic.</p><div className="mt-7 grid grid-cols-2 gap-3 text-xs"><div className="rounded-xl bg-primary-foreground/10 p-3"><p className="text-primary-foreground/60">Uptime</p><p className="mt-1 text-lg font-semibold">99.9%</p></div><div className="rounded-xl bg-primary-foreground/10 p-3"><p className="text-primary-foreground/60">Avg. answer</p><p className="mt-1 text-lg font-semibold">2.1 sec</p></div></div></Panel></div></>;
}

// --------------------------------------------------------------- calendar
const weekDayNames = ["Mon", "Tue", "Wed", "Thu", "Fri"] as const;
const monthNames = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
function mondayOf(date: Date) { const d = new Date(date); const day = (d.getDay() + 6) % 7; d.setDate(d.getDate() - day); d.setHours(0, 0, 0, 0); return d; }

export function CalendarPage() {
  const staffList = useStaff(); const appointments = useAppointments(); const clients = useClients();
  const [staffFilter, setStaffFilter] = useState("all");
  const [dialog, setDialog] = useState<"new" | "details" | "timeoff" | null>(null);
  const [selected, setSelected] = useState<AppointmentRow | null>(null);
  const [weekOffset, setWeekOffset] = useState(0);
  const week = useMemo(() => {
    const monday = mondayOf(new Date());
    monday.setDate(monday.getDate() + weekOffset * 7);
    return weekDayNames.map((name, i) => { const d = new Date(monday); d.setDate(d.getDate() + i); return { name, label: `${name} ${d.getDate()}`, date: d }; });
  }, [weekOffset]);
  const first = week[0]!; const last = week[4]!;
  const rangeLabel = `${monthNames[first.date.getMonth()]} ${first.date.getDate()}–${first.date.getMonth() === last.date.getMonth() ? "" : `${monthNames[last.date.getMonth()]} `}${last.date.getDate()}, ${last.date.getFullYear()}`;
  const sameDay = (a: Date, b: Date) => a.toDateString() === b.toDateString();
  const visible = appointments.filter((a) => a.status !== "Cancelled" && (staffFilter === "all" || a.staff_id === staffFilter) && week.some((d) => sameDay(d.date, new Date(a.start_time))));
  const clientName = (id: string | null) => clients.find((c) => c.id === id)?.name ?? "Unknown client";
  return <><PageHeader title="Calendar" description={`${rangeLabel} · Clinic time`} action={<div className="flex flex-wrap gap-2"><Button variant="outline" className="rounded-[10px]" onClick={() => setDialog("timeoff")}>Add time off</Button><Button className="rounded-[10px]" onClick={() => { setSelected(null); setDialog("new"); }}><Plus />New appointment</Button></div>} /><Panel className="overflow-hidden p-0"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-border p-4"><div className="flex gap-2"><Button size="icon" variant="outline" aria-label="Previous week" onClick={() => setWeekOffset(weekOffset - 1)}><ChevronLeft /></Button><Button variant="outline" onClick={() => { setWeekOffset(0); toast.success("Showing this week"); }}>Today</Button><Button size="icon" variant="outline" aria-label="Next week" onClick={() => setWeekOffset(weekOffset + 1)}><ChevronRight /></Button></div><Select value={staffFilter} onValueChange={setStaffFilter}><SelectTrigger className="w-full sm:w-[210px]"><Filter /><SelectValue placeholder="All staff" /></SelectTrigger><SelectContent><SelectItem value="all">All staff</SelectItem>{staffList.map((s) => <SelectItem key={s.id} value={s.id}>{s.name}</SelectItem>)}</SelectContent></Select></div><div className="overflow-x-auto"><div className="min-w-[900px]"><div className="grid grid-cols-[70px_repeat(5,1fr)] border-b border-border bg-muted/40"><div />{week.map((d) => <div key={d.label} className="border-l border-border p-3 text-center text-sm font-semibold">{d.label}</div>)}</div><div className="relative grid h-[620px] grid-cols-[70px_repeat(5,1fr)]">{["8 AM", "9 AM", "10 AM", "11 AM", "12 PM", "1 PM", "2 PM", "3 PM", "4 PM", "5 PM"].map((t, i) => <div key={t} className="col-span-6 grid grid-cols-[70px_1fr] border-b border-border" style={{ gridRow: i + 1 }}><span className="p-2 text-right text-[11px] text-muted-foreground">{t}</span><span className="border-l border-border" /></div>)}{visible.map((a) => { const start = new Date(a.start_time); const col = week.findIndex((d) => sameDay(d.date, start)) + 2; const row = Math.min(10, Math.max(1, start.getHours() - 7)); return <Button key={a.id} variant="outline" onClick={() => { setSelected(a); setDialog("details"); }} className="z-10 m-1 h-auto items-start justify-start whitespace-normal border-success-border bg-success-soft p-2 text-left text-success-strong hover:bg-success-soft" style={{ gridColumn: col, gridRow: row }}><span><b className="block text-xs">{formatTime(a.start_time)}</b><span className="block text-xs">{clientName(a.client_id)}</span><span className="block text-[10px] opacity-75">{a.service}</span></span></Button>; })}</div></div></div>{!visible.length && <div className="border-t border-border p-4 text-center text-sm text-muted-foreground">No appointments scheduled for this week.</div>}</Panel><AppointmentDialog mode={dialog} onClose={() => { setDialog(null); setSelected(null); }} appointment={selected} /></>;
}

function AppointmentDialog({ mode, onClose, appointment }: { mode: "new" | "details" | "timeoff" | null; onClose: () => void; appointment: AppointmentRow | null }) {
  const clientList = useClients(); const staffList = useStaff();
  const create = useCreateAppointment(); const reschedule = useRescheduleAppointment(); const cancel = useCancelAppointment();
  const [action, setAction] = useState<"view" | "reschedule" | "cancel">("view");
  const [clientId, setClientId] = useState(""); const [staffId, setStaffId] = useState("");
  const [service, setService] = useState("Dental Cleaning");
  const [date, setDate] = useState(""); const [time, setTime] = useState("10:30");
  const [reason, setReason] = useState("");
  const detail = mode === "details" && appointment !== null;

  useEffect(() => {
    if (!mode) return;
    setAction("view"); setReason("");
    const start = appointment ? new Date(appointment.start_time) : new Date();
    setDate(start.toISOString().slice(0, 10));
    setTime(appointment ? start.toTimeString().slice(0, 5) : "10:30");
    setClientId(appointment?.client_id ?? clientList[0]?.id ?? "");
    setStaffId(appointment?.staff_id ?? staffList[0]?.id ?? "");
    setService(appointment?.service ?? "Dental Cleaning");
  }, [mode, appointment, clientList, staffList]);

  if (!mode) return null;
  const appointmentClient = clientList.find((c) => c.id === (appointment?.client_id ?? clientId));

  const save = async () => {
    try {
      if (mode === "timeoff") { toast.success("Time off noted for the schedule"); onClose(); return; }
      if (detail && action === "cancel" && appointment) { await cancel.mutateAsync({ id: appointment.id, reason }); toast.success("Appointment cancelled"); }
      else if (detail && appointment) { await reschedule.mutateAsync({ id: appointment.id, date, time }); toast.success("Appointment rescheduled"); }
      else {
        if (!clientId || !staffId || !service.trim()) { toast.error("Choose a client, a practitioner and a service."); return; }
        await create.mutateAsync({ clientId, staffId, service, date, time }); toast.success("Appointment created");
      }
      onClose();
    } catch { toast.error("Could not save the appointment."); }
  };

  return <Dialog open onOpenChange={(o) => { if (!o) { setAction("view"); onClose(); } }}><DialogContent className="max-h-[85vh] overflow-y-auto rounded-2xl"><DialogHeader><DialogTitle>{mode === "new" ? "New Appointment" : mode === "timeoff" ? "Add Time Off" : action === "reschedule" ? "Reschedule Appointment" : action === "cancel" ? "Cancel Appointment" : "Appointment Details"}</DialogTitle><DialogDescription>{detail ? `${appointmentClient?.name ?? "Client"} · ${appointment?.service}` : "Update the clinic calendar."}</DialogDescription></DialogHeader>{mode === "timeoff" ? <div className="grid gap-4"><div><Label>Team member</Label><Select value={staffId} onValueChange={setStaffId}><SelectTrigger className="mt-2"><SelectValue /></SelectTrigger><SelectContent>{staffList.map((s) => <SelectItem value={s.id} key={s.id}>{s.name}</SelectItem>)}</SelectContent></Select></div><div className="grid grid-cols-2 gap-3"><Input type="date" value={date} onChange={(e) => setDate(e.target.value)} /><Input type="time" value={time} onChange={(e) => setTime(e.target.value)} /></div><Textarea placeholder="Reason (optional)" value={reason} onChange={(e) => setReason(e.target.value)} /></div>
    : detail && action === "view" ? <div className="space-y-3 rounded-xl bg-muted p-4 text-sm"><p><b>Time:</b> {formatDate(appointment.start_time)}, {formatTime(appointment.start_time)}</p><p><b>Practitioner:</b> {staffList.find((s) => s.id === appointment.staff_id)?.name ?? "Unassigned"}</p><p><b>Service:</b> {appointment.service}</p><p><b>Source:</b> {appointment.source}</p><StatusBadge status={appointment.status} /></div>
    : action === "cancel" ? <Textarea placeholder="Cancellation reason" value={reason} onChange={(e) => setReason(e.target.value)} />
    : <div className="grid gap-4">{!detail && <div><Label>Client</Label><Select value={clientId} onValueChange={setClientId}><SelectTrigger className="mt-2"><SelectValue placeholder="Select a client" /></SelectTrigger><SelectContent>{clientList.map((c) => <SelectItem value={c.id} key={c.id}>{c.name}</SelectItem>)}</SelectContent></Select></div>}{!detail && <div><Label>Practitioner</Label><Select value={staffId} onValueChange={setStaffId}><SelectTrigger className="mt-2"><SelectValue placeholder="Select a practitioner" /></SelectTrigger><SelectContent>{staffList.map((s) => <SelectItem value={s.id} key={s.id}>{s.name}</SelectItem>)}</SelectContent></Select></div>}{!detail && <div><Label>Service</Label><Input className="mt-2" value={service} onChange={(e) => setService(e.target.value)} /></div>}<div className="grid grid-cols-2 gap-3"><Input type="date" value={date} onChange={(e) => setDate(e.target.value)} /><Input type="time" value={time} onChange={(e) => setTime(e.target.value)} /></div></div>}
    <DialogFooter>{detail && action === "view" ? <><Button variant="destructive" onClick={() => setAction("cancel")}>Cancel appointment</Button><Button variant="outline" onClick={() => setAction("reschedule")}>Reschedule</Button></> : <><Button variant="outline" onClick={() => { setAction("view"); onClose(); }}>Cancel</Button><Button onClick={() => void save()}>{action === "cancel" ? "Confirm cancellation" : "Save"}</Button></>}</DialogFooter></DialogContent></Dialog>;
}

// ---------------------------------------------------------------- clients
function AddClientDialog({ open, onOpenChange }: { open: boolean; onOpenChange: (o: boolean) => void }) {
  const addClient = useAddClient();
  const [name, setName] = useState(""); const [phone, setPhone] = useState(""); const [email, setEmail] = useState(""); const [notes, setNotes] = useState(""); const [error, setError] = useState("");
  const submit = async () => {
    if (!name.trim() || !phone.trim()) { setError("Full name and phone number are required."); return; }
    if (email.trim() && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())) { setError("Enter a valid email address."); return; }
    try {
      await addClient.mutateAsync({ name, phone, email, notes });
      setError(""); setName(""); setPhone(""); setEmail(""); setNotes(""); onOpenChange(false);
      toast.success("Client added successfully");
    } catch { setError("Could not save the client. Please try again."); }
  };
  return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="max-h-[85vh] overflow-y-auto rounded-2xl"><DialogHeader><DialogTitle>Add client</DialogTitle><DialogDescription>Create a client profile for your clinic.</DialogDescription></DialogHeader>{error && <div className="rounded-[10px] border border-destructive/30 bg-destructive/5 p-3 text-sm text-destructive">{error}</div>}<div className="grid gap-4"><div><Label htmlFor="client-name">Full name</Label><Input id="client-name" className={cn(field, "mt-2")} value={name} onChange={(e) => setName(e.target.value)} placeholder="Sarah Al-Hamad" /></div><div><Label htmlFor="client-phone">Phone number</Label><Input id="client-phone" type="tel" inputMode="tel" className={cn(field, "mt-2")} value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="+965 9912 3456" /></div><div><Label htmlFor="client-email">Email address <span className="text-muted-foreground">(optional)</span></Label><Input id="client-email" type="email" inputMode="email" className={cn(field, "mt-2")} value={email} onChange={(e) => setEmail(e.target.value)} placeholder="client@example.com" /></div><div><Label htmlFor="client-notes">Notes <span className="text-muted-foreground">(optional)</span></Label><Textarea id="client-notes" className="mt-2" value={notes} onChange={(e) => setNotes(e.target.value)} placeholder="Anything the team should know" /></div></div><DialogFooter><Button variant="outline" onClick={() => onOpenChange(false)}>Cancel</Button><Button disabled={addClient.isPending} onClick={() => void submit()}>Add client</Button></DialogFooter></DialogContent></Dialog>;
}

function EditClientDialog({ client, onClose }: { client: Client | null; onClose: () => void }) {
  const updateClient = useUpdateClient();
  const [name, setName] = useState(""); const [phone, setPhone] = useState(""); const [email, setEmail] = useState("");
  useEffect(() => { if (client) { setName(client.full_name); setPhone(client.phone); setEmail(client.email ?? ""); } }, [client]);
  if (!client) return null;
  return <Dialog open onOpenChange={(o) => { if (!o) onClose(); }}><DialogContent className="rounded-2xl"><DialogHeader><DialogTitle>Edit client</DialogTitle><DialogDescription>Update {client.name}'s contact details.</DialogDescription></DialogHeader><div className="grid gap-4"><div><Label htmlFor="edit-client-name">Full name</Label><Input id="edit-client-name" className={cn(field, "mt-2")} value={name} onChange={(e) => setName(e.target.value)} /></div><div><Label htmlFor="edit-client-phone">Phone number</Label><Input id="edit-client-phone" className={cn(field, "mt-2")} value={phone} onChange={(e) => setPhone(e.target.value)} /></div><div><Label htmlFor="edit-client-email">Email address</Label><Input id="edit-client-email" className={cn(field, "mt-2")} value={email} onChange={(e) => setEmail(e.target.value)} /></div></div><DialogFooter><Button variant="outline" onClick={onClose}>Cancel</Button><Button disabled={updateClient.isPending} onClick={async () => { if (!name.trim() || !phone.trim()) { toast.error("Full name and phone number are required."); return; } try { await updateClient.mutateAsync({ id: client.id, full_name: name.trim(), phone: phone.trim(), email: email.trim() || null }); toast.success("Client updated"); onClose(); } catch { toast.error("Could not update the client."); } }}>Save changes</Button></DialogFooter></DialogContent></Dialog>;
}

export function ClientsPage() {
  const clientList = useClients(); const appointments = useAppointments();
  const [q, setQ] = useState(""); const [status, setStatus] = useState("all"); const [open, setOpen] = useState(false); const [editing, setEditing] = useState<Client | null>(null);
  const bookingsOf = (id: string) => appointments.filter((a) => a.client_id === id).length;
  const rows = clientList.filter((c) => `${c.name} ${c.phone} ${c.email ?? ""}`.toLowerCase().includes(q.toLowerCase()) && (status === "all" || clientStatus(bookingsOf(c.id)) === status));
  const copy = (value: string) => { if (typeof navigator !== "undefined" && navigator.clipboard) { navigator.clipboard.writeText(value).then(() => toast.success("Phone number copied")).catch(() => toast.error("Could not copy the number")); } else toast.error("Copying is not available here"); };
  return <><PageHeader title="Clients" description={`${clientList.length} client profiles from calls and bookings.`} action={<Button onClick={() => setOpen(true)}><Plus />Add client</Button>} /><div className="mb-4 grid gap-4 sm:grid-cols-3"><IconStat icon={Sparkles} label="Client records" value={String(clientList.length)} note="in your clinic" /><IconStat icon={CalendarDays} label="Active bookings" value={String(appointments.filter((a) => a.status === "Booked").length)} note="scheduled" /><IconStat icon={Clock} label="Follow-ups" value={String(appointments.filter((a) => a.status === "Needs Review").length)} note="pending" /></div><Panel><div className="mb-4 flex flex-col gap-3 sm:flex-row"><div className="flex-1 sm:max-w-md"><SearchBox value={q} onChange={setQ} placeholder="Search clients" /></div><Select value={status} onValueChange={setStatus}><SelectTrigger className="w-full sm:w-[190px]"><Filter /><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">All clients</SelectItem><SelectItem value="Active Patient">Active Patient</SelectItem><SelectItem value="New Client">New Client</SelectItem></SelectContent></Select></div>{rows.length ? rows.map((c) => { const apt = appointments.find((a) => a.client_id === c.id && a.status === "Booked"); const bookings = bookingsOf(c.id); return <DataRow key={c.id}><div className="flex items-center gap-3"><Avatar initials={c.initials} /><div className="min-w-0"><Link to="/clients/$id" params={{ id: c.id }} className="font-semibold hover:underline">{c.name}</Link><p className="truncate text-xs text-muted-foreground">{c.phone} · {dash(c.email)}</p></div></div><div className="text-sm"><p>{clientStatus(bookings)}</p><p className="text-xs text-muted-foreground">{bookings} bookings</p></div><div className="text-sm">{apt ? <><p>{apt.service}</p><p className="text-xs text-muted-foreground">{formatDate(apt.start_time)} · {formatTime(apt.start_time)}</p></> : <span className="text-muted-foreground">No upcoming appointment</span>}</div><DropdownMenu><DropdownMenuTrigger asChild><Button variant="ghost" size="icon" aria-label={`Actions for ${c.name}`}><MoreHorizontal /></Button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuItem asChild><Link to="/clients/$id" params={{ id: c.id }}>View profile</Link></DropdownMenuItem><DropdownMenuItem onSelect={() => setEditing(c)}>Edit client</DropdownMenuItem><DropdownMenuItem onSelect={() => copy(c.phone)}>Copy phone number</DropdownMenuItem><DropdownMenuItem asChild><Link to="/calendar">Book appointment</Link></DropdownMenuItem></DropdownMenuContent></DropdownMenu></DataRow>; }) : <Empty>No clients match your search.</Empty>}</Panel><AddClientDialog open={open} onOpenChange={setOpen} /><EditClientDialog client={editing} onClose={() => setEditing(null)} /></>;
}

export function ClientDetailPage({ id }: { id: string }) {
  const clientList = useClients(); const appointments = useAppointments(); const conversations = useConversations(); const staffList = useStaff();
  const notes = useClientNotes(id); const addNote = useAddClientNote();
  const [note, setNote] = useState(""); const [editing, setEditing] = useState<Client | null>(null);
  const c = clientList.find((x) => x.id === id);
  if (!c) return <><Link to="/clients" className="mb-5 inline-flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground"><ArrowLeft className="size-4" />Back to Clients</Link><Empty>This client could not be found.</Empty></>;
  const related = appointments.filter((a) => a.client_id === c.id);
  const upcoming = related.filter((a) => a.status === "Booked");
  const history = related.filter((a) => a.status !== "Booked");
  const calls = conversations.filter((x) => x.client_id === c.id);
  const bookings = related.length;
  return <><Link to="/clients" className="mb-5 inline-flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground"><ArrowLeft className="size-4" />Back to Clients</Link><div className="mb-6 flex flex-wrap items-center gap-4"><Avatar initials={c.initials} large /><div className="mr-auto"><h1 className="text-2xl font-semibold">{c.name}</h1><p className="text-sm text-muted-foreground">{clientStatus(bookings)} · {bookings} bookings</p></div><Button variant="outline" onClick={() => setEditing(c)}>Edit client</Button><Button asChild><Link to="/calendar"><Plus />Book appointment</Link></Button></div><div className="grid gap-6 xl:grid-cols-[1.35fr_.65fr]"><div className="space-y-6"><Panel><PanelTitle>Upcoming appointments</PanelTitle>{upcoming.length ? upcoming.map((a) => <div key={a.id} className="mb-3 rounded-xl border border-success-border bg-success-soft p-4 last:mb-0"><div className="flex flex-wrap justify-between gap-3"><div><p className="font-semibold">{a.service}</p><p className="mt-1 text-sm text-muted-foreground">{formatDate(a.start_time)} · {formatTime(a.start_time)} · {durationLabel(a.start_time, a.end_time)}</p><p className="mt-1 text-sm">{staffList.find((s) => s.id === a.staff_id)?.name ?? "Unassigned"}</p></div><StatusBadge status={a.status} /></div><p className="mt-3 text-xs font-medium text-success-strong">{a.source}</p></div>) : <Empty>No upcoming appointments.</Empty>}</Panel><Panel><PanelTitle>Appointment history</PanelTitle>{history.length ? history.map((a) => <DataRow key={a.id}><div><p className="font-medium">{a.service}</p><p className="text-xs text-muted-foreground">{formatDate(a.start_time)}</p></div><span className="text-sm">{staffList.find((s) => s.id === a.staff_id)?.name ?? "Unassigned"}</span><StatusBadge status={a.status} /><Button variant="ghost" size="icon" aria-label={`Open notes for ${a.service}`} onClick={() => toast.info(a.notes ? a.notes : "No notes recorded for this visit.")}><FileText /></Button></DataRow>) : <Empty>No past appointments.</Empty>}</Panel><Panel><PanelTitle>Call history</PanelTitle>{calls.length ? calls.map((x) => <Link key={x.id} to="/conversations/$id" params={{ id: x.id }} className="block border-b border-border py-4 last:border-0"><div className="flex flex-wrap justify-between gap-2"><div><p className="font-medium">{x.title}</p><p className="mt-1 text-xs text-muted-foreground">{formatDate(x.started_at)} · {formatDuration(x.duration_seconds)}</p></div><StatusBadge status={x.status} /></div><p className="mt-2 text-sm text-muted-foreground">{dash(x.summary)}</p></Link>) : <Empty>No calls recorded.</Empty>}</Panel></div><div className="space-y-6"><Panel><PanelTitle>Contact information</PanelTitle><dl className="space-y-4 text-sm"><div><dt className="text-xs text-muted-foreground">Phone number</dt><dd className="mt-1"><a className="hover:underline" href={`tel:${c.phone}`}>{c.phone}</a></dd></div><div><dt className="text-xs text-muted-foreground">Email address</dt><dd className="mt-1 break-all">{dash(c.email)}</dd></div><div><dt className="text-xs text-muted-foreground">Client since</dt><dd className="mt-1">{formatDate(c.created_at)}</dd></div></dl></Panel><Panel><PanelTitle>Internal notes</PanelTitle><div className="space-y-3">{c.notes && <div className="rounded-xl bg-muted p-3 text-sm">{c.notes}</div>}{notes.map((n) => <div key={n.id} className="rounded-xl bg-muted p-3 text-sm">{n.note}<p className="mt-1 text-[10px] text-muted-foreground">{formatDate(n.created_at)}</p></div>)}{!c.notes && !notes.length && <Empty>No notes yet.</Empty>}</div><Textarea value={note} onChange={(e) => setNote(e.target.value)} className="mt-4" placeholder="Add an internal note" /><Button className="mt-3 w-full" disabled={!note.trim() || addNote.isPending} onClick={async () => { try { await addNote.mutateAsync({ clientId: c.id, note }); setNote(""); toast.success("Note saved"); } catch { toast.error("Could not save the note."); } }}>Save note</Button></Panel></div></div><EditClientDialog client={editing} onClose={() => setEditing(null)} /></>;
}

// ------------------------------------------------------------------ staff
function AddStaffDialog({ open, onOpenChange }: { open: boolean; onOpenChange: (o: boolean) => void }) {
  const addStaff = useAddStaff();
  const [name, setName] = useState(""); const [specialty, setSpecialty] = useState(""); const [phone, setPhone] = useState(""); const [email, setEmail] = useState(""); const [services, setServices] = useState(""); const [days, setDays] = useState("Mon–Thu"); const [error, setError] = useState("");
  const submit = async () => {
    if (!name.trim() || !specialty.trim()) { setError("Full name and specialty / role are required."); return; }
    if (!services.trim()) { setError("Add at least one service."); return; }
    if (email.trim() && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())) { setError("Enter a valid email address."); return; }
    try {
      await addStaff.mutateAsync({ name, specialty, phone, email, services, days });
      setError(""); setName(""); setSpecialty(""); setPhone(""); setEmail(""); setServices(""); setDays("Mon–Thu"); onOpenChange(false);
      toast.success("Staff member added successfully");
    } catch { setError("Could not save the staff member. Please try again."); }
  };
  return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="max-h-[85vh] overflow-y-auto rounded-2xl"><DialogHeader><DialogTitle>Add staff member</DialogTitle><DialogDescription>Add a team member to your clinic directory.</DialogDescription></DialogHeader>{error && <div className="rounded-[10px] border border-destructive/30 bg-destructive/5 p-3 text-sm text-destructive">{error}</div>}<div className="grid gap-4"><div><Label htmlFor="staff-name">Full name</Label><Input id="staff-name" className={cn(field, "mt-2")} value={name} onChange={(e) => setName(e.target.value)} placeholder="Dr. Layla Kareem" /></div><div><Label htmlFor="staff-specialty">Specialty / role</Label><Input id="staff-specialty" className={cn(field, "mt-2")} value={specialty} onChange={(e) => setSpecialty(e.target.value)} placeholder="Orthodontics" /></div><div><Label htmlFor="staff-phone">Phone number <span className="text-muted-foreground">(optional)</span></Label><Input id="staff-phone" type="tel" inputMode="tel" className={cn(field, "mt-2")} value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="+965 2225 4104" /></div><div><Label htmlFor="staff-email">Email address <span className="text-muted-foreground">(optional)</span></Label><Input id="staff-email" type="email" inputMode="email" className={cn(field, "mt-2")} value={email} onChange={(e) => setEmail(e.target.value)} placeholder="name@dentalzone.com" /></div><div><Label htmlFor="staff-services">Services</Label><Input id="staff-services" className={cn(field, "mt-2")} value={services} onChange={(e) => setServices(e.target.value)} placeholder="Dental Cleaning, Consultation" /><p className="mt-1 text-xs text-muted-foreground">Separate services with commas.</p></div><div><Label htmlFor="staff-days">Working days / availability</Label><Input id="staff-days" className={cn(field, "mt-2")} value={days} onChange={(e) => setDays(e.target.value)} placeholder="Mon–Thu, 9:00–17:00" /></div></div><DialogFooter><Button variant="outline" onClick={() => onOpenChange(false)}>Cancel</Button><Button disabled={addStaff.isPending} onClick={() => void submit()}>Add staff member</Button></DialogFooter></DialogContent></Dialog>;
}

function EditStaffDialog({ member, onClose }: { member: StaffMember | null; onClose: () => void }) {
  const updateStaff = useUpdateStaff();
  const [name, setName] = useState(""); const [specialty, setSpecialty] = useState(""); const [phone, setPhone] = useState(""); const [email, setEmail] = useState(""); const [services, setServices] = useState("");
  useEffect(() => { if (member) { setName(member.full_name); setSpecialty(member.specialty); setPhone(member.phone ?? ""); setEmail(member.email ?? ""); setServices(member.services.join(", ")); } }, [member]);
  if (!member) return null;
  return <Dialog open onOpenChange={(o) => { if (!o) onClose(); }}><DialogContent className="max-h-[85vh] overflow-y-auto rounded-2xl"><DialogHeader><DialogTitle>Edit staff member</DialogTitle><DialogDescription>Update {member.name}'s details and services.</DialogDescription></DialogHeader><div className="grid gap-4"><div><Label htmlFor="edit-staff-name">Full name</Label><Input id="edit-staff-name" className={cn(field, "mt-2")} value={name} onChange={(e) => setName(e.target.value)} /></div><div><Label htmlFor="edit-staff-specialty">Specialty / role</Label><Input id="edit-staff-specialty" className={cn(field, "mt-2")} value={specialty} onChange={(e) => setSpecialty(e.target.value)} /></div><div><Label htmlFor="edit-staff-phone">Phone number</Label><Input id="edit-staff-phone" className={cn(field, "mt-2")} value={phone} onChange={(e) => setPhone(e.target.value)} /></div><div><Label htmlFor="edit-staff-email">Email address</Label><Input id="edit-staff-email" className={cn(field, "mt-2")} value={email} onChange={(e) => setEmail(e.target.value)} /></div><div><Label htmlFor="edit-staff-services">Services</Label><Input id="edit-staff-services" className={cn(field, "mt-2")} value={services} onChange={(e) => setServices(e.target.value)} /><p className="mt-1 text-xs text-muted-foreground">Separate services with commas.</p></div></div><DialogFooter><Button variant="outline" onClick={onClose}>Cancel</Button><Button disabled={updateStaff.isPending} onClick={async () => { if (!name.trim() || !specialty.trim()) { toast.error("Full name and specialty are required."); return; } try { await updateStaff.mutateAsync({ id: member.id, full_name: name.trim(), specialty: specialty.trim(), phone: phone.trim() || null, email: email.trim() || null, services: services.split(",").map((s) => s.trim()).filter(Boolean) }); toast.success("Staff member updated"); onClose(); } catch { toast.error("Could not update the staff member."); } }}>Save changes</Button></DialogFooter></DialogContent></Dialog>;
}

export function StaffPage() {
  const staffList = useStaff();
  const [q, setQ] = useState(""); const [specialty, setSpecialty] = useState("all"); const [open, setOpen] = useState(false);
  const specialties = [...new Set(staffList.map((s) => s.specialty))];
  const rows = staffList.filter((s) => `${s.name} ${s.specialty} ${s.services.join(" ")}`.toLowerCase().includes(q.toLowerCase()) && (specialty === "all" || s.specialty === specialty));
  const groups = [...new Set(rows.map((s) => s.specialty))];
  return <><PageHeader title="Staff" description="Manage your clinic team, hours, and assigned services." action={<Button onClick={() => setOpen(true)}><Plus />Add staff member</Button>} /><div className="mb-6 flex flex-col gap-3 sm:flex-row"><div className="flex-1 sm:max-w-md"><SearchBox value={q} onChange={setQ} placeholder="Search staff or services" /></div><Select value={specialty} onValueChange={setSpecialty}><SelectTrigger className="w-full sm:w-[220px]"><Filter /><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">All specialties</SelectItem>{specialties.map((s) => <SelectItem key={s} value={s}>{s}</SelectItem>)}</SelectContent></Select></div>{groups.length ? groups.map((g) => <section key={g} className="mb-7"><h2 className="mb-3 text-sm font-semibold text-muted-foreground">{g}</h2><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{rows.filter((s) => s.specialty === g).map((s) => <Link key={s.id} to="/staff/$id" params={{ id: s.id }}><Panel className="h-full transition-shadow hover:shadow-modal"><div className="flex items-center gap-4"><Avatar initials={s.initials} large /><div><h3 className="font-semibold">{s.name}</h3><p className="text-sm text-muted-foreground">{s.specialty}</p><div className="mt-2"><StatusBadge status={s.active ? "Active" : "Inactive"} /></div></div></div><div className="mt-5 border-t border-border pt-4 text-xs text-muted-foreground">{s.services.length} services</div></Panel></Link>)}</div></section>) : <Empty>No staff match your search.</Empty>}<AddStaffDialog open={open} onOpenChange={setOpen} /></>;
}

export function StaffDetailPage({ id }: { id: string }) {
  const staffList = useStaff(); const appointments = useAppointments(); const clients = useClients();
  const availability = useAvailability(id); const saveAvailability = useSaveAvailability();
  const [editing, setEditing] = useState(false); const [editDetails, setEditDetails] = useState<StaffMember | null>(null);
  const [rows, setRows] = useState<{ day_of_week: number; start_time: string; end_time: string; is_available: boolean }[]>([]);
  useEffect(() => {
    setRows([1, 2, 3, 4, 5].map((day) => {
      const found = availability.find((a) => a.day_of_week === day);
      return { day_of_week: day, start_time: (found?.start_time ?? "09:00").slice(0, 5), end_time: (found?.end_time ?? "17:00").slice(0, 5), is_available: found?.is_available ?? false };
    }));
  }, [availability]);
  const s = staffList.find((x) => x.id === id);
  if (!s) return <><Link to="/staff" className="mb-5 inline-flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground"><ArrowLeft className="size-4" />Back to Staff</Link><Empty>This team member could not be found.</Empty></>;
  const setRow = (day: number, patch: Partial<{ start_time: string; end_time: string; is_available: boolean }>) => setRows((prev) => prev.map((r) => (r.day_of_week === day ? { ...r, ...patch } : r)));
  const upcoming = appointments.filter((a) => a.staff_id === s.id && a.status === "Booked");
  return <><Link to="/staff" className="mb-5 inline-flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground"><ArrowLeft className="size-4" />Back to Staff</Link><div className="mb-6 flex flex-wrap items-center gap-4"><Avatar initials={s.initials} large /><div className="mr-auto"><h1 className="text-2xl font-semibold">{s.name}</h1><p className="text-sm text-muted-foreground">{s.specialty}</p></div><Button variant="ghost" onClick={() => setEditDetails(s)}>Edit details</Button><Button variant="outline" onClick={() => { setEditing(true); toast.info("Availability is now editable below."); }}>Manage availability</Button></div><div className="grid gap-6 xl:grid-cols-[1.2fr_.8fr]"><Panel><PanelTitle detail={<Button size="sm" disabled={!editing || saveAvailability.isPending} onClick={async () => { try { await saveAvailability.mutateAsync({ staffId: s.id, rows }); setEditing(false); toast.success("Schedule updated"); } catch { toast.error("Could not save the schedule."); } }}>Save hours</Button>}>Weekly schedule</PanelTitle>{rows.map((r) => <div key={r.day_of_week} className="flex flex-wrap items-center gap-2 border-b border-border py-3 last:border-0 sm:gap-3"><span className="w-full text-sm font-medium sm:w-[100px]">{DAY_NAMES[r.day_of_week]}</span><Input type="time" className="w-[110px] flex-1" value={r.start_time} disabled={!editing} onChange={(e) => setRow(r.day_of_week, { start_time: e.target.value })} /><Input type="time" className="w-[110px] flex-1" value={r.end_time} disabled={!editing} onChange={(e) => setRow(r.day_of_week, { end_time: e.target.value })} /><label className="flex items-center gap-1 text-xs text-muted-foreground"><input type="checkbox" checked={r.is_available} disabled={!editing} onChange={(e) => setRow(r.day_of_week, { is_available: e.target.checked })} /> Working</label></div>)}<p className="mt-3 text-xs text-muted-foreground">Working days: {rows.filter((r) => r.is_available).map((r) => DAY_NAMES[r.day_of_week]?.slice(0, 3)).join(", ") || "None set"}</p></Panel><div className="space-y-6"><Panel><PanelTitle>Contact details</PanelTitle><p className="break-all text-sm">{dash(s.email)}</p><p className="mt-2 text-sm">{dash(s.phone)}</p></Panel><Panel><PanelTitle detail={<Button size="sm" variant="ghost" onClick={() => setEditDetails(s)}>Edit</Button>}>Assigned services</PanelTitle>{s.services.length ? <div className="flex flex-wrap gap-2">{s.services.map((x) => <span className="rounded-full border border-border bg-muted px-3 py-1 text-xs" key={x}>{x}</span>)}</div> : <Empty>No services assigned yet.</Empty>}</Panel><Panel><PanelTitle>Upcoming appointments</PanelTitle>{upcoming.length ? upcoming.map((a) => <div key={a.id} className="border-b border-border py-3 last:border-0"><p className="text-sm font-medium">{clients.find((c) => c.id === a.client_id)?.name ?? "Unknown client"}</p><p className="text-xs text-muted-foreground">{formatDate(a.start_time)} · {formatTime(a.start_time)} · {a.service}</p></div>) : <Empty>No upcoming appointments.</Empty>}</Panel></div></div><EditStaffDialog member={editDetails} onClose={() => setEditDetails(null)} /></>;
}

// ---------------------------------------------------------- conversations
export function ConversationsPage() {
  const conversations = useConversations(); const clients = useClients();
  const [q, setQ] = useState(""); const [status, setStatus] = useState("all");
  const clientOf = (c: ConversationRow) => clients.find((x) => x.id === c.client_id);
  const rows = conversations.filter((c) => { const cl = clientOf(c); return `${cl?.name ?? ""} ${c.caller_phone ?? ""} ${c.title}`.toLowerCase().includes(q.toLowerCase()) && (status === "all" || c.status === status); });
  return <><PageHeader title="Conversations" description="Review every call answered for your clinic." /><Panel><div className="mb-5 flex flex-col gap-3 sm:flex-row"><div className="flex-1"><SearchBox value={q} onChange={setQ} placeholder="Search caller or reason" /></div><Select value={status} onValueChange={setStatus}><SelectTrigger className="w-full sm:w-[180px]"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">All statuses</SelectItem><SelectItem value="Booked">Booked</SelectItem><SelectItem value="Needs Review">Needs Review</SelectItem><SelectItem value="Missed">Missed</SelectItem></SelectContent></Select></div>{rows.length ? rows.map((c) => { const cl = clientOf(c); return <DataRow key={c.id}><div className="flex items-center gap-3"><Avatar initials={cl?.initials ?? "?"} /><div className="min-w-0"><Link to="/conversations/$id" params={{ id: c.id }} className="font-semibold hover:underline">{c.title}</Link><p className="truncate text-xs text-muted-foreground">{cl?.name ?? "Unknown caller"} · {dash(c.caller_phone)}</p></div></div><span className="text-sm text-muted-foreground">{formatDate(c.started_at)}<br />{formatTime(c.started_at)}</span><span className="text-sm tabular-nums">{formatDuration(c.duration_seconds)}</span><StatusBadge status={c.status} /></DataRow>; }) : <Empty>No conversations match these filters.</Empty>}</Panel></>;
}

export function ConversationDetailPage({ id }: { id: string }) {
  const conversations = useConversations(); const clients = useClients(); const appointments = useAppointments(); const staffList = useStaff();
  const c = conversations.find((x) => x.id === id);
  if (!c) return <><Link to="/conversations" className="mb-5 inline-flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground"><ArrowLeft className="size-4" />Back to Conversations</Link><Empty>This conversation could not be found.</Empty></>;
  const client = clients.find((x) => x.id === c.client_id);
  const appt = appointments.find((a) => a.id === c.appointment_id);
  const turns = parseTranscript(c.transcript);
  return <><Link to="/conversations" className="mb-5 inline-flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground"><ArrowLeft className="size-4" />Back to Conversations</Link><PageHeader title={c.title} description={`${formatDate(c.started_at)} at ${formatTime(c.started_at)}`} action={<StatusBadge status={c.status} />} /><div className="grid gap-6 xl:grid-cols-[1.4fr_.6fr]"><div className="space-y-6"><Panel><PanelTitle detail={<span className="text-[10px] font-semibold uppercase text-success">Apero summary</span>}>Conversation summary</PanelTitle><p className="text-sm leading-6">{dash(c.summary)}</p><div className="mt-5 grid grid-cols-2 gap-3 rounded-xl bg-muted p-3 text-xs sm:grid-cols-4"><div><span className="text-muted-foreground">Date</span><b className="mt-1 block">{formatDate(c.started_at)}</b></div><div><span className="text-muted-foreground">Time</span><b className="mt-1 block">{formatTime(c.started_at)}</b></div><div><span className="text-muted-foreground">Duration</span><b className="mt-1 block">{formatDuration(c.duration_seconds)}</b></div><div><span className="text-muted-foreground">Channel</span><b className="mt-1 block text-success">Voice call</b></div></div></Panel><Panel><PanelTitle>Call recording</PanelTitle><div className="flex flex-wrap items-center gap-3 rounded-xl bg-nav-active p-4 sm:gap-4">{c.recording_url?.trim() ? <audio controls src={c.recording_url} className="min-w-0 flex-1" aria-label="Call recording" /> : <span className="flex-1 text-sm text-muted-foreground">Recording unavailable</span>}<span className="text-xs tabular-nums">{formatDuration(c.duration_seconds)}</span></div></Panel><Panel><PanelTitle detail={<span className="text-xs text-muted-foreground">{turns.length} turns</span>}>Full transcript</PanelTitle>{turns.length ? <div className="space-y-5">{turns.map((turn, i) => { const apero = turn.speaker === "Apero Receptionist"; return <div key={i} className={cn("flex gap-2", !apero && "justify-end")}><div className={cn("max-w-[82%]", !apero && "text-right")}><p className="mb-1 text-[10px] text-muted-foreground"><b className="text-foreground">{turn.speaker}</b> · {turn.time}</p><p className={cn("rounded-xl px-3 py-2 text-left text-sm", apero ? "bg-nav-active" : "bg-primary text-primary-foreground")}>{turn.text}</p></div></div>; })}</div> : <Empty>No transcript is available for this call.</Empty>}</Panel></div><div className="space-y-6"><Panel><PanelTitle detail={<StatusBadge status={c.status} />}>Extracted information</PanelTitle><dl className="space-y-3 text-sm"><div className="flex justify-between gap-3"><dt className="text-muted-foreground">Client</dt><dd className="font-medium">{client?.name ?? "Unknown"}</dd></div><div className="flex justify-between gap-3"><dt className="text-muted-foreground">Phone</dt><dd>{dash(c.caller_phone ?? client?.phone)}</dd></div><div className="flex justify-between gap-3"><dt className="text-muted-foreground">Outcome</dt><dd className="text-right">{dash(c.outcome)}</dd></div><div className="flex justify-between gap-3"><dt className="text-muted-foreground">Practitioner</dt><dd>{appt ? staffList.find((s) => s.id === appt.staff_id)?.name ?? "—" : "—"}</dd></div></dl></Panel>{client && <Panel><PanelTitle>Client profile</PanelTitle><div className="flex items-center gap-3"><Avatar initials={client.initials} /><div><p className="font-semibold">{client.name}</p><p className="text-xs text-muted-foreground">{client.phone}</p></div></div><Button variant="outline" className="mt-5 w-full" asChild><Link to="/clients/$id" params={{ id: client.id }}>View full profile</Link></Button></Panel>}{appt && <Panel><PanelTitle>Related appointment</PanelTitle><p className="font-medium">{appt.service}</p><p className="mt-1 text-xs text-muted-foreground">{formatDate(appt.start_time)} · {formatTime(appt.start_time)}</p><div className="mt-3"><StatusBadge status={appt.status} /></div><Button variant="ghost" className="mt-4 w-full" asChild><Link to="/calendar">Open calendar</Link></Button></Panel>}</div></div></>;
}

// ---------------------------------------------------------------- billing
export function BillingPage() {
  const { profile } = useAuth();
  const downloadInvoice = (id: string, date: string, description: string) => {
    try {
      const body = `Apero Invoice\n\nInvoice: ${id}\nDate: ${date}\nDescription: ${description}\nAmount: $—\nStatus: Paid\n\nThis is a sample invoice; live billing is not connected yet.\n`;
      const url = URL.createObjectURL(new Blob([body], { type: "text/plain" }));
      const a = document.createElement("a"); a.href = url; a.download = `${id}.txt`; a.click(); URL.revokeObjectURL(url);
      toast.success(`Invoice ${id} downloaded (sample)`);
    } catch { toast.error("Could not prepare the invoice download."); }
  };
  return <><PageHeader title="Billing" description="Manage your Apero plan, payment method, and billing receipts." /><Panel className="mb-6"><div className="flex flex-col justify-between gap-5 sm:flex-row"><div><div className="flex items-center gap-2"><h2 className="text-lg font-semibold">Current Plan</h2><StatusBadge status="Active" /></div><p className="mt-5 text-xl font-semibold">Apero Receptionist</p><p className="text-sm text-muted-foreground">Clinic Standard Edition</p><p className="mt-5 text-3xl font-semibold">$— <span className="text-sm font-normal text-muted-foreground">/ month</span></p></div><div className="sm:text-right"><p className="text-sm text-muted-foreground">Renewal date</p><p className="mt-1 font-semibold">October 13, 2026</p><p className="mt-6 text-xs text-muted-foreground">Auto-renew active</p><Button variant="outline" className="mt-3" onClick={() => toast.info("Subscription management opens once payments are connected.")}>Manage subscription</Button></div></div><div className="mt-6 grid gap-3 border-t border-border pt-5 sm:grid-cols-2">{["Unlimited inbound call answering", "Real-time clinic scheduling", "Arabic & English reception", "Client information capture"].map((x) => <div key={x} className="flex items-center gap-2 text-sm"><Check className="size-4 shrink-0 text-success" />{x}</div>)}</div></Panel><div className="grid gap-6 xl:grid-cols-[.7fr_1.3fr]"><Panel><PanelTitle>Payment method</PanelTitle><div className="rounded-xl bg-primary p-4 text-primary-foreground"><CreditCard className="size-6" /><p className="mt-6 text-lg font-semibold tracking-widest">•••• 4242</p><div className="mt-4 flex justify-between text-xs"><span>{profile?.full_name ?? "Clinic account"}</span><span>08 / 2028</span></div></div><Button variant="outline" className="mt-4 w-full" onClick={() => toast.info("Card updates open in secure checkout once payments are connected.")}>Update payment method</Button></Panel><Panel className="overflow-x-auto"><PanelTitle>Invoice history</PanelTitle>{invoices.map((i) => <DataRow key={i.id}><div><p className="font-medium">{i.description}</p><p className="text-xs text-muted-foreground">{i.id}</p></div><span className="text-sm">{i.date}</span><div><p className="text-sm font-medium">{i.amount}</p><StatusBadge status={i.status} /></div><Button size="icon" variant="ghost" onClick={() => downloadInvoice(i.id, i.date, i.description)} aria-label={`Download invoice ${i.id}`}><Download /></Button></DataRow>)}</Panel></div></>;
}

// ---------------------------------------------------------------- account
export function AccountPage() {
  const navigate = useNavigate();
  const { profile, updatePassword, signOut, refreshProfile } = useAuth();
  const [logout, setLogout] = useState(false); const [pw, setPw] = useState(""); const [current, setCurrent] = useState("");
  const [name, setName] = useState(""); const [phone, setPhone] = useState("");
  useEffect(() => { if (profile) { setName(profile.full_name); setPhone(profile.phone ?? ""); } }, [profile]);
  const rules = [pw.length >= 8, /[A-Z]/.test(pw), /\d/.test(pw)];
  const saveProfile = async () => {
    if (!profile) return;
    const { db } = await import("@/lib/db");
    const { error } = await db.from("profiles").update({ full_name: name.trim(), phone: phone.trim() || null }).eq("id", profile.id);
    if (error) { toast.error("Could not save your changes."); return; }
    await refreshProfile(); toast.success("Changes saved successfully");
  };
  return <><PageHeader title="Account & Profile" description="Manage your personal information and account security." /><div className="grid gap-6 xl:grid-cols-2"><Panel><PanelTitle>Personal information</PanelTitle><div className="grid gap-4"><div><Label htmlFor="profile-name">Full name</Label><Input id="profile-name" className="mt-2" value={name} onChange={(e) => setName(e.target.value)} /></div><div><Label htmlFor="profile-email">Email address</Label><Input id="profile-email" type="email" className="mt-2" value={profile?.email ?? ""} readOnly /></div><div><Label htmlFor="profile-phone">Phone number</Label><Input id="profile-phone" type="tel" inputMode="tel" className="mt-2" value={phone} onChange={(e) => setPhone(e.target.value)} /></div><Button className="justify-self-end" onClick={() => void saveProfile()}>Save changes</Button></div></Panel><Panel><PanelTitle>Password</PanelTitle><div className="grid gap-4"><div><Label htmlFor="current-password">Current password</Label><Input id="current-password" className="mt-2" type="password" value={current} onChange={(e) => setCurrent(e.target.value)} /></div><div><Label htmlFor="new-password">New password</Label><Input id="new-password" className="mt-2" type="password" value={pw} onChange={(e) => setPw(e.target.value)} /></div><div className="space-y-2 rounded-xl bg-muted p-3 text-xs">{["At least 8 characters", "At least 1 uppercase letter", "At least 1 number"].map((r, i) => <div key={r} className={cn("flex items-center gap-2", rules[i] ? "text-success-strong" : "text-muted-foreground")}><CheckCircle2 className="size-3" />{r}</div>)}</div><Button disabled={!rules.every(Boolean)} onClick={async () => { if (!current.trim()) { toast.error("Enter your current password."); return; } const { error } = await updatePassword(pw); if (error) { toast.error("Could not update the password."); return; } setPw(""); setCurrent(""); toast.success("Password updated successfully"); }}>Update password</Button></div></Panel><Panel><PanelTitle>Need help?</PanelTitle><p className="text-sm text-muted-foreground">Contact Apero Support for help with your account or clinic workspace.</p><Button variant="outline" className="mt-4" asChild><Link to="/support"><Mail />Contact Support</Link></Button></Panel><Panel><PanelTitle>Log out</PanelTitle><p className="text-sm text-muted-foreground">Sign out of your Apero account on this device.</p><Button variant="destructive" className="mt-4" onClick={() => setLogout(true)}>Log out</Button></Panel></div><Dialog open={logout} onOpenChange={setLogout}><DialogContent className="rounded-2xl"><DialogHeader><DialogTitle>Log out?</DialogTitle><DialogDescription>Are you sure you want to log out of Apero?</DialogDescription></DialogHeader><DialogFooter><Button variant="outline" onClick={() => setLogout(false)}>Cancel</Button><Button variant="destructive" onClick={async () => { await signOut(); toast.success("You have been logged out"); void navigate({ to: "/login" }); }}>Log out</Button></DialogFooter></DialogContent></Dialog></>;
}

export { initialsOf };

// ---------------------------------------------------------------- support
const supportCategories = ["Appointment issue", "Call quality", "Client records", "Staff & scheduling", "Billing question", "Account access", "Feature request", "Bug report", "Something else"] as const;

export function SupportPage() {
  const { profile } = useAuth();
  const clinicName = useClinicName();
  const [category, setCategory] = useState<string>(supportCategories[0]);
  const [subject, setSubject] = useState(""); const [message, setMessage] = useState("");
  const [sent, setSent] = useState(false); const [error, setError] = useState("");
  if (sent) return <><PageHeader title="Support" description={`We’ve received your request for ${clinicName}.`} /><Panel className="text-center"><CheckCircle2 className="mx-auto size-12 text-success" /><h2 className="mt-4 text-lg font-semibold">Request sent</h2><p className="mx-auto mt-2 max-w-md text-sm text-muted-foreground">Our team replies within one business day at {profile?.email ?? "your email address"}.</p><Button className="mt-6" variant="outline" onClick={() => { setSent(false); setSubject(""); setMessage(""); }}>Send another request</Button></Panel></>;
  return <><PageHeader title="Support" description="Tell us what you need and the Apero team will help." /><div className="grid gap-6 xl:grid-cols-[1.4fr_.6fr]"><Panel><PanelTitle>New support request</PanelTitle>{error && <div className="mb-4 rounded-[10px] border border-destructive/30 bg-destructive/5 p-3 text-sm text-destructive">{error}</div>}<div className="grid gap-4"><div><Label htmlFor="support-category">Category</Label><Select value={category} onValueChange={setCategory}><SelectTrigger id="support-category" className="mt-2"><SelectValue /></SelectTrigger><SelectContent>{supportCategories.map((c) => <SelectItem key={c} value={c}>{c}</SelectItem>)}</SelectContent></Select></div><div><Label htmlFor="support-subject">Subject</Label><Input id="support-subject" className={cn(field, "mt-2")} value={subject} onChange={(e) => setSubject(e.target.value)} placeholder="Short summary" /></div><div><Label htmlFor="support-message">How can we help?</Label><Textarea id="support-message" className="mt-2 min-h-[140px]" value={message} onChange={(e) => setMessage(e.target.value)} placeholder="Describe what happened" /></div><Button className="justify-self-end" onClick={() => { if (!subject.trim() || !message.trim()) { setError("Add a subject and a short description."); return; } setError(""); setSent(true); toast.success("Support request sent"); }}>Send request</Button></div></Panel><Panel><PanelTitle>Contact Apero</PanelTitle><p className="text-sm text-muted-foreground">Prefer email? Reach our team directly.</p><Button variant="outline" className="mt-4 w-full" asChild><a href="mailto:apero.hq@gmail.com"><Mail />apero.hq@gmail.com</a></Button><p className="mt-5 text-xs text-muted-foreground">Support hours: Sunday–Thursday, 9:00–18:00.</p></Panel></div></>;
}
